script:
.prose {
  color: var(--ink-gray-7);
  line-height: 1.75;
  font-size: 14px;
}

.prose h1 {
  color: #111827;
  font-weight: 800;
  font-size: 2.25em;
  margin-top: 0;
  margin-bottom: 0.8888889em;
  line-height: 1.1111111;
}

.prose h2 {
  color: #111827;
  font-weight: 700;
  font-size: 1.5em;
  margin-top: 2em;
  margin-bottom: 1em;
  line-height: 1.3333333;
}

.prose h3 {
  color: #111827;
  font-weight: 600;
  font-size: 1.25em;
  margin-top: 1.6em;
  margin-bottom: 0.6em;
  line-height: 1.6;
}

.prose h4 {
  color: #111827;
  font-weight: 600;
  margin-top: 1.5em;
  margin-bottom: 0.5em;
  line-height: 1.5;
}

.prose blockquote {
  font-weight: 500;
  font-style: italic;
  color: #111827;
  border-left-width: 0.25rem;
  border-left-color: #e5e7eb;
  margin-top: 1.6em;
  margin-bottom: 1.6em;
  padding-left: 1em;
}

.prose ul {
  list-style-type: disc;
  margin-top: 1.25em;
  margin-bottom: 1.25em;
  padding-left: 1.625em;
}

.prose ol {
  list-style-type: decimal;
  margin-top: 1.25em;
  margin-bottom: 1.25em;
  padding-left: 1.625em;
}

.prose li {
  margin-top: 0.5em;
  margin-bottom: 0.5em;
}

.prose ul li::marker {
  color: #e2e2e2;
}

.prose ol li::marker {
  color: #999;
}

.prose li p {
  margin-top: 0.25em;
  margin-bottom: 0.25em;
}

.prose a {
  color: #111827;
  text-decoration: underline;
  font-weight: 500;
}

.prose strong {
  color: #111827;
  font-weight: 600;
}

.prose hr {
  border-color: #e5e7eb;
  border-top-width: 1px;
  margin-top: 3em;
  margin-bottom: 3em;
}

.prose table {
  box-sizing: border-box;
  border-style: solid;
  border-width: 0;
  text-indent: 0;
  border-color: inherit;
  border-collapse: collapse;
  width: 100%;
  margin-top: 16px;
  margin-bottom: 16px;
  line-height: 1.7;
  table-layout: fixed;
  min-width: 75px;
}

.prose table thead {
  background-color: #fff;
}

.prose table tr {
  border-top: 1px solid #e5e7eb;
  border-bottom: 1px solid #e5e7eb;
}

.prose table th {
  background-color: var(--surface-gray-2);
}

.prose table th,
.prose table td {
  border-left: 1px solid #e5e7eb;
  border-right: 1px solid #e5e7eb;
  padding: 0.5rem;
  vertical-align: top;
  text-align: start;
}

.prose ul[data-type="taskList"] {
  padding: 0;
  list-style: none;
}

.prose ul[data-type="taskList"] li {
  align-items: flex-start;
  margin: 0;
  display: flex;
}

.prose ul[data-type="taskList"] li > label {
  -webkit-user-select: none;
  user-select: none;
  flex: none;
  align-items: center;
  height: 1lh;
  margin-top: 0.25rem;
  margin-right: 0.5rem;
  display: flex;
}

.prose ul[data-type="taskList"] li > div {
  flex: auto;
  margin-bottom: 0;
}

.prose ul[data-type="taskList"] input[type="checkbox"] {
  cursor: pointer;
  color: #171717;
  border-radius: 4px;
  width: 14px;
  height: 14px;
}

.prose code {
  display: block;
  width: 100%;
  color: #24292e;
  border: 1px solid var(--outline-gray-2);
  caret-color: #24292e;
  background: #f6f8fa;
  border-radius: 8px;
  padding: 0.45rem 0.75rem;
  font-family:
    ui-monospace,
    Menlo,
    Monaco,
    Cascadia Mono,
    Segoe UI Mono,
    Roboto Mono,
    Oxygen Mono,
    Ubuntu Mono,
    Source Code Pro,
    Fira Mono,
    Droid Sans Mono,
    Consolas,
    Courier New,
    monospace;
  font-size: 12px;
  line-height: 1.7;
}
